import {shouldContinueToolLoop, accumulateUsage} from './orchestratorHelpers.js';
import type {ToolRegistry} from './tools/registry.js';
import type {ToolCall, UsageMetadata} from '../types/ai.js';

// All three conditions matter; dropping the registry check spins the tool loop.

const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
const REGISTRY = {} as ToolRegistry;

describe('shouldContinueToolLoop', () => {
  it('continues when the model requested a tool and a registry can run it', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
  });

  it('stops when no registry is configured, whatever the model asked for', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
  });

  it('stops when the model named no tool', () => {
    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
  });

  it('stops when the model finished for a reason other than tool use', () => {
    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
  });
});

describe('accumulateUsage', () => {
  it('sums token fields when both operands are defined', () => {
    const a: UsageMetadata = {inputTokens: 10, outputTokens: 4, totalTokens: 14};
    const b: UsageMetadata = {inputTokens: 25, outputTokens: 8, totalTokens: 33};
    expect(accumulateUsage(a, b)).toEqual({inputTokens: 35, outputTokens: 12, totalTokens: 47});
  });

  it('returns the defined side when one operand is undefined', () => {
    const usage: UsageMetadata = {inputTokens: 5, outputTokens: 2, totalTokens: 7};
    expect(accumulateUsage(undefined, usage)).toEqual(usage);
    expect(accumulateUsage(usage, undefined)).toEqual(usage);
  });

  it('returns undefined when both operands are undefined', () => {
    expect(accumulateUsage(undefined, undefined)).toBeUndefined();
  });
});
12:- A hook passed through `orchestrator.hooks` is forwarded to the orchestrator and fires ([validated by: forwards an orchestrator hook, so one passed through the config actually fires](../../src/config.test.ts#L19)).
13:- An engine built with no `orchestrator` key at all still processes a message, so the field is optional in fact and not only in the type ([validated by: processes a message when the config declares no orchestrator key at all](../../src/config.test.ts#L95)).
14:- A `beforeModelResponse` hook installed through config is handed the base system prompt built from `prompt`, proving the hook reaches the orchestrator and is wired into the prompt pipeline rather than only being stored on the config ([validated by: hands a config-installed beforeModelResponse hook the built base system prompt, not merely storing it](../../src/config.test.ts#L108)).
15:- The value the hook returns then replaces the system prompt the provider receives; this is exercised at the orchestrator layer because `HalEngineConfig.provider` takes a `ProviderConfig` and offers no seam to inject a recording provider through config ([validated by: replaces system prompt with returned value](../../src/orchestration/chatOrchestrator.test.ts#L221)).
16:- For a session that completes without error the hooks fire in the order `beforeSession` → `beforeUserInput` → `afterUserInput` → `beforeModelResponse` → `afterModelResponse` → `afterSession` ([validated by: fires the lifecycle hooks in documented order for a session that completes without error](../../src/config.test.ts#L132)).
17:- A `beforeSession` that throws reaches the caller as a rejection, and also runs `onError` with the thrown error and then `afterSession`, because the call sits inside the same `try`/`finally` as the rest of the turn. An `afterSession` hook called under this condition can infer the session never advanced past `beforeSession`: no user-input hooks ran, no model response was generated, and no tool rounds were started — a cleanup hook that allocates in `beforeSession` and frees in `afterSession` will therefore always see the allocation and the release on the same error path ([validated by: runs onError then afterSession when it throws, and still rejects to the caller](../../src/orchestration/chatOrchestrator.test.ts#L116)).
18:- `afterModelResponse` is called once per user message after the round loop exits and receives the `UsageMetadata` summed across every provider call in that turn, rather than only the final round's usage ([validated by: reports usage summed across every provider call when a turn runs through two tool rounds](../../src/orchestration/chatOrchestrator.acceptance.test.ts#L53)).
19:- When some rounds in a turn omit `usage`, `afterModelResponse` receives the sum of the rounds that reported it, and when no round in the turn reported `usage`, it receives `undefined` ([validated by: counts the rounds that reported usage when some omit it, and reports undefined when none did](../../src/orchestration/chatOrchestrator.acceptance.test.ts#L63)).
23:- The engine's `start()` method rejects the returned promise when it cannot bind the configured port, rather than emitting an unhandled error event that would take the process down ([validated by: rejects instead of taking the process down with an unhandled error event](../../src/config.test.ts#L174)).
